<?php if ($totalAsistencia): ?><div class="table-scroll"><table class="attendance-table"><thead><tr><th>Materia</th><th>Presentes</th><th>Ausencias</th><th>Última clase</th></tr></thead><tbody>
<?php foreach ($asistenciaPorMateria as $clave => $asistencia): if (!$asistencia['total']) continue;
    $nombreMateriaAsistencia = $clave;
    foreach ($filasAsistencia as $registro) { if (hv_clave_materia($registro['materia']) === $clave) { $nombreMateriaAsistencia = $registro['materia']; break; } }
?><tr><td><strong><?php echo hv_escape($nombreMateriaAsistencia); ?></strong></td><td class="attendance-number attendance-good"><?php echo (int)$asistencia['presentes']; ?> / <?php echo (int)$asistencia['total']; ?></td><td class="attendance-number <?php echo $asistencia['ausencias'] ? 'attendance-alert' : ''; ?>"><?php echo (int)$asistencia['ausencias']; ?></td><td><?php echo hv_fecha($asistencia['ultima_fecha'], '—'); ?></td></tr><?php endforeach; ?>
</tbody></table></div><?php else: ?><div class="empty-state"><i class="bi bi-calendar-x"></i><strong>Sin controles en este rango</strong><p>Seleccione otro periodo para consultar sus registros.</p></div><?php endif; ?>
<?php if ($filasAsistencia): ?><details class="activity-detail"><summary>Ver registros de asistencia (<?php echo count($filasAsistencia); ?>)</summary><div class="table-scroll"><table class="activity-table"><thead><tr><th>Fecha de clase</th><th>Materia</th><th>Asistencia</th><th>Justificación</th></tr></thead><tbody><?php foreach ($filasAsistencia as $registro): ?><tr><td><?php echo hv_fecha($registro['fechas_clase']); ?></td><td><?php echo hv_escape($registro['materia']); ?></td><td><?php echo hv_escape($registro['asistencias']); ?></td><td><?php echo hv_mostrar($registro['justificacion'] === '0' ? '' : $registro['justificacion'], '—'); ?></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?>
